def Enqueue(InputData):
global Queue
global HeadPointer
global TailPointer
global NumberItems
if NumberItems >= 20:
return False
if TailPointer <= -1:
TailPointer = 0
HeadPointer = 0
Queue[TailPointer] = InputData
else:
TailPointer = TailPointer + 1
if TailPointer == 20:
     TailPointer = 0
Queue[TailPointer] = InputData
NumberItems +=1
return True
