public static Boolean Enqueue(Integer InputData){
if(NumberItems >= 20){
    return false;
}
if(TailPointer <= -1){
    TailPointer = 0;
    HeadPointer = 0;
    Queue[TailPointer] = InputData;
}else{
           TailPointer++;
    if(TailPointer == 20){
           TailPointer = 0;
    }
    Queue[TailPointer] = InputData;
}
NumberItems++;
return true;
}

