1 mark each
 •   Dequeue() header (and close) and checking if queue is empty (NumberItems = 0) and returning –1
 •   Returning data at HeadPointer
 •   Incrementing HeadPointer …
 •   … and catching if = 20 to return to 0
 •   Decrementing NumberItems
 •   Resetting HeadPointer and TailPointer when queue is empty
Example program code:
Python
def Dequeue():
global Queue
global HeadPointer
global TailPointer
global NumberItems
if NumberItems <= 0:
return -1
else:
ReturnValue = Queue[HeadPointer]
HeadPointer +=1
if HeadPointer >= 20:
     HeadPointer = 0
NumberItems -=1
if NumberItems == 0:
     HeadPointer = -1
     TailPointer = -1
return ReturnValue
VB.NET
Function Dequeue()
Dim ReturnValue As Integer
If NumberItems <= 0 Then
Return -1
Else
ReturnValue = Queue(HeadPointer)
HeadPointer = HeadPointer + 1
If HeadPointer >= 20 Then
  HeadPointer = 0
End If
NumberItems = NumberItems – 1
If NumberItems = 0 Then
  HeadPointer = -1
  TailPointer = -1
End If
Return ReturnValue
End If
End Function
Java
public static Integer Dequeue(){
Integer ReturnValue;
if(NumberItems <= 0){
    return -1;
}else{
    ReturnValue = Queue[HeadPointer];
    HeadPointer++;
    if(HeadPointer >= 20){
           HeadPointer = 0;
    }
    NumberItems--;
    if(NumberItems == 0){
           HeadPointer = -1;
           TailPointer = -1;
    }
    return ReturnValue;
}
}

